{
  "staging.stg_lever__application": {
    "items": [
      {
        "problem": "Applications archived before their creation timestamp are retained instead of deleted.",
        "about": "requirement",
        "evidence_in_work": "where generation checks required fields and enums but adds no archived_at comparison",
        "source": "archived_at IS NULL OR created_at IS NULL OR try_cast(archived_at as timestamp) >= try_cast(created_at as timestamp); on_failure: delete_row",
        "importance": 4,
        "reason": "Invalid application histories can affect open-opportunity counts and downstream reporting."
      }
    ],
    "fewer_reason": "No additional independently supported problems were found in this application's mapping and filters."
  },
  "staging.stg_lever__archive_reason": {
    "items": [],
    "fewer_reason": "The visible mapping, required-key filtering, and uniqueness handling reveal no specific additional problem."
  },
  "staging.stg_lever__contact_email": {
    "items": [
      {
        "problem": "The implemented email pattern requires a literal dot while the contract's pattern uses an unescaped dot, potentially nullifying values accepted by the specified rule.",
        "about": "requirement",
        "evidence_in_work": "'^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$'",
        "source": "email RLIKE '^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+.[A-Za-z]{2,}$'",
        "importance": 2,
        "reason": "This is a narrow edge case but changes the precise acceptance rule."
      }
    ],
    "fewer_reason": "The remaining visible contact-email transformations follow the supplied specification."
  },
  "staging.stg_lever__contact_link": {
    "items": [
      {
        "problem": "URL validation accepts leading whitespace and uppercase schemes but returns the original string, rather than nullifying strings that fail the contract's literal prefix rule.",
        "about": "requirement",
        "evidence_in_work": "regexp_matches(trim(cast(r.\"link\" AS VARCHAR)), '^https?://', 'i')",
        "source": "link IS NULL OR link RLIKE '^https?://'; on_failure: nullify_field",
        "importance": 2,
        "reason": "Malformed-by-contract links can survive staging and be selected as profile links."
      }
    ],
    "fewer_reason": "No other specific discrepancy is supported by the available link specification."
  },
  "staging.stg_lever__contact_phone": {
    "items": [],
    "fewer_reason": "The visible source mapping and required contact_id check match the supplied rules."
  },
  "staging.stg_lever__feedback_form": {
    "items": [],
    "fewer_reason": "No specific discrepancy was found in the visible mapping, timestamp conversion, and key handling."
  },
  "staging.stg_lever__feedback_form_field": {
    "items": [],
    "fewer_reason": "The table was created, but its detailed contract is not included in the review materials, so additional field-level concerns would be speculative."
  },
  "staging.stg_lever__interview": {
    "items": [
      {
        "problem": "Interview durations outside the allowed 0–600 range are cast but never nullified.",
        "about": "requirement",
        "evidence_in_work": "try_cast(r.\"duration\" AS DOUBLE) AS duration",
        "source": "duration IS NULL OR (duration >= 0 AND duration <= 600); on_failure: nullify_field",
        "importance": 4,
        "reason": "Invalid durations contaminate multiple interview-time averages and totals."
      },
      {
        "problem": "Interviews canceled before creation are not removed.",
        "about": "requirement",
        "evidence_in_work": "valid filters end with creator_user_id IS NOT NULL",
        "source": "canceled_at IS NULL OR created_at IS NULL OR try_cast(canceled_at as timestamp) >= try_cast(created_at as timestamp); on_failure: delete_row",
        "importance": 4,
        "reason": "Unusable interviews remain in counts, cancellation rates, and downstream joins."
      },
      {
        "problem": "Malformed timezone values are passed through rather than nullified.",
        "about": "requirement",
        "evidence_in_work": "try_cast(r.\"timezone\" AS VARCHAR(10)) AS timezone",
        "source": "timezone IS NULL OR timezone RLIKE '^[A-Za-z_]+/[A-Za-z_]+$'; on_failure: nullify_field",
        "importance": 3,
        "reason": "The staging output fails the explicit scheduling-information quality rule."
      },
      {
        "problem": "Calendar URLs with leading whitespace or uppercase schemes are accepted and preserved despite the specified prefix check.",
        "about": "requirement",
        "evidence_in_work": "regexp_matches(trim(cast(r.\"gcal_event_url\" AS VARCHAR)), '^https?://', 'i')",
        "source": "gcal_event_url IS NULL OR gcal_event_url RLIKE '^https?://'",
        "importance": 2,
        "reason": "This affects URL cleanliness rather than the main numerical metrics."
      }
    ],
    "fewer_reason": "Four independently supported validation discrepancies were found; further concerns would repeat these or require unseen data."
  },
  "staging.stg_lever__interview_feedback": {
    "items": [],
    "fewer_reason": "The supplied contract requires only interview_id and feedback_form_id, and the visible implementation preserves that scope."
  },
  "staging.stg_lever__interviewer_user": {
    "items": [],
    "fewer_reason": "The implementation uses the documented raw.interviewer_user source and preserves duplicate assignments as required downstream."
  },
  "staging.stg_lever__offer": {
    "items": [
      {
        "problem": "Offer rows are filtered using requisition status values instead of retaining rows and nullifying invalid offer statuses.",
        "about": "requirement",
        "evidence_in_work": "'status': \"status IN ('open','closed','cancelled','draft','pending')\"",
        "source": "status IS NULL OR status IN ('draft', 'pending', 'sent', 'accepted', 'declined', 'rescinded'); on_failure: nullify_field",
        "importance": 5,
        "reason": "Valid sent, accepted, declined, rescinded, and null-status offers can disappear entirely while invalid requisition-like statuses survive."
      }
    ],
    "fewer_reason": "The shared status-filter bug is the principal supported issue; no additional independent offer-mapping problem was found."
  },
  "staging.stg_lever__opportunity": {
    "items": [
      {
        "problem": "Opportunities archived before creation are retained.",
        "about": "requirement",
        "evidence_in_work": "where generation adds no archived_at >= created_at condition",
        "source": "archived_at IS NULL OR try_cast(archived_at as timestamp) >= try_cast(created_at as timestamp); on_failure: delete_row",
        "importance": 4,
        "reason": "These records feed nearly every candidate and hiring model and can produce invalid lifecycle durations."
      },
      {
        "problem": "Opportunities updated before creation are retained.",
        "about": "requirement",
        "evidence_in_work": "try_cast(r.\"updated_at\" AS TIMESTAMP) with no chronological validation",
        "source": "updated_at IS NULL OR try_cast(updated_at as timestamp) >= try_cast(created_at as timestamp); on_failure: delete_row",
        "importance": 4,
        "reason": "The required deletion step is omitted for a central pipeline entity."
      },
      {
        "problem": "The contract's opportunity date rules do not exempt a missing created_at, but the implementation retains such rows even when archived_at or updated_at is present.",
        "about": "requirement",
        "evidence_in_work": "created_at is TRY_CAST and is not included among required-field filters",
        "source": "archived_at IS NULL OR try_cast(archived_at as timestamp) >= try_cast(created_at as timestamp)",
        "importance": 3,
        "reason": "Missing creation times can leave records that fail chronological validation and later mart not-null expectations."
      }
    ],
    "fewer_reason": "The supported issues concern omitted chronological validation; other mappings are consistent with the available source columns."
  },
  "staging.stg_lever__opportunity_source": {
    "items": [],
    "fewer_reason": "No detailed per-table contract is supplied for this table, and no visible execution or mapping issue remains."
  },
  "staging.stg_lever__opportunity_stage_history": {
    "items": [],
    "fewer_reason": "The visible mapping matches the supplied columns and required identifiers."
  },
  "staging.stg_lever__opportunity_tag": {
    "items": [],
    "fewer_reason": "The implementation preserves tag values and duplicates and checks the required opportunity identifier."
  },
  "staging.stg_lever__posting": {
    "items": [
      {
        "problem": "Null or invalid optional requisition codes cause entire postings to be deleted instead of retaining the posting with a null code.",
        "about": "requirement",
        "evidence_in_work": "if col=='requisition_code': where.append(\"        requisition_code LIKE 'REQ-%'\")",
        "source": "requisition_code IS NULL OR requisition_code LIKE 'REQ-%'; on_failure: nullify_field",
        "importance": 5,
        "reason": "This can remove valid postings and their entire downstream reporting population."
      },
      {
        "problem": "Invalid commitment categories are passed through instead of nullified.",
        "about": "requirement",
        "evidence_in_work": "try_cast(r.\"categories_commitment\" AS VARCHAR(50))",
        "source": "categories_commitment IN ('full-time', 'part-time', 'contract', 'internship'); on_failure: nullify_field",
        "importance": 3,
        "reason": "Invalid employment categories can create incorrect reporting segments."
      },
      {
        "problem": "Invalid seniority categories are passed through instead of nullified.",
        "about": "requirement",
        "evidence_in_work": "try_cast(r.\"categories_level\" AS VARCHAR(50))",
        "source": "categories_level IN ('Entry', 'Mid', 'Senior', 'Lead', 'Principal', 'Executive'); on_failure: nullify_field",
        "importance": 3,
        "reason": "Job-level segmentation and best-level summaries can include prohibited values."
      },
      {
        "problem": "Postings updated before creation are not deleted.",
        "about": "requirement",
        "evidence_in_work": "valid filters contain no updated_at comparison",
        "source": "updated_at IS NULL OR created_at IS NULL OR try_cast(updated_at as timestamp) >= try_cast(created_at as timestamp); on_failure: delete_row",
        "importance": 3,
        "reason": "The explicit chronological quality rule is omitted."
      },
      {
        "problem": "Blank posting titles survive because trimming is implemented but the required positive-length check is not.",
        "about": "requirement",
        "evidence_in_work": "length checks apply to ('user_id','requisition_id','interview_id','posting_id','stage_id','opportunity_id','user_name')",
        "source": "LENGTH(TRIM(posting_title)) > 0; on_failure: delete_row",
        "importance": 3,
        "reason": "Empty-title postings remain usable as business entities despite the required rejection rule."
      }
    ],
    "fewer_reason": "Five distinct discrepancies are supported by the visible posting contract and generator."
  },
  "staging.stg_lever__posting_interview": {
    "items": [],
    "fewer_reason": "Both documented identifiers are mapped and checked, with relationship duplicates preserved."
  },
  "staging.stg_lever__posting_tag": {
    "items": [],
    "fewer_reason": "The visible implementation follows the supplied identifier and tag requirements."
  },
  "staging.stg_lever__requisition": {
    "items": [
      {
        "problem": "Uniqueness is enforced on the pair of requisition_id and requisition_code rather than independently on both declared unique columns.",
        "about": "requirement",
        "evidence_in_work": "PARTITION BY {', '.join(unique)}",
        "source": "requisition_id constraints: [not_null, unique]; requisition_code constraints: [not_null, unique]",
        "importance": 4,
        "reason": "Repeated IDs with different codes or repeated codes with different IDs can survive and multiply downstream joins."
      },
      {
        "problem": "Unsupported compensation currencies and intervals are not nullified.",
        "about": "requirement",
        "evidence_in_work": "fields are TRY_CAST without currency or interval CASE expressions",
        "source": "currency IN ('USD', 'EUR', 'GBP', 'CNY', 'CAD', 'AUD'); interval IN ('hourly', 'monthly', 'yearly'); on_failure: nullify_field",
        "importance": 3,
        "reason": "Invalid compensation units can make salary data misleading."
      },
      {
        "problem": "Negative compensation minima and maxima below minima are retained.",
        "about": "requirement",
        "evidence_in_work": "try_cast(r.\"compensation_band_min\" AS DOUBLE) and try_cast(r.\"compensation_band_max\" AS DOUBLE)",
        "source": "compensation_band_min >= 0; compensation_band_max >= compensation_band_min; on_failure: nullify_field",
        "importance": 4,
        "reason": "Invalid bands distort salary-range widths in hiring-manager reporting."
      },
      {
        "problem": "Headcount consistency rules, including clearing total headcount for infinite requisitions, are not applied.",
        "about": "requirement",
        "evidence_in_work": "headcount fields are only TRY_CAST",
        "source": "headcount_hired <= headcount_total; headcount_infinite IS FALSE OR headcount_total IS NULL; on_failure: nullify_field",
        "importance": 3,
        "reason": "The output can contain contradictory hiring requirements."
      },
      {
        "problem": "Boolean raw headcount fields are converted to integers without checking whether the original numeric headcount information has already been lost.",
        "about": "data",
        "evidence_in_work": "lever_start.yaml: headcount_hired: BOOLEAN; headcount_total: BOOLEAN",
        "source": "headcount_hired data_type: INT; headcount_total data_type: INT",
        "importance": 2,
        "reason": "If these represent actual counts rather than flags, casting booleans produces only 0/1 and cannot recover the intended values."
      }
    ],
    "fewer_reason": "Five distinct issues are supported; the remaining mappings and required-value filters show no additional concrete discrepancy."
  },
  "staging.stg_lever__requisition_offer": {
    "items": [],
    "fewer_reason": "Both required relationship keys are mapped and checked without prohibited deduplication."
  },
  "staging.stg_lever__requisition_posting": {
    "items": [],
    "fewer_reason": "The visible implementation preserves relationship rows and validates the required keys."
  },
  "staging.stg_lever__resume": {
    "items": [],
    "fewer_reason": "The detailed resume staging contract is not supplied, so no additional specific contract violation can be established."
  },
  "staging.stg_lever__stage": {
    "items": [],
    "fewer_reason": "The initial source-key error was repaired, and the final visible mapping and validation match the supplied stage contract."
  },
  "staging.stg_lever__user": {
    "items": [
      {
        "problem": "Users deactivated before account creation are not deleted.",
        "about": "requirement",
        "evidence_in_work": "where generation contains no deactivated_at comparison",
        "source": "deactivated_at IS NULL OR created_at IS NULL OR try_cast(deactivated_at as timestamp) >= try_cast(created_at as timestamp); on_failure: delete_row",
        "importance": 4,
        "reason": "Invalid user accounts remain available to enrich and qualify interviewer and manager records."
      },
      {
        "problem": "The email validator is stricter than the literal contract pattern and can delete users whose addresses satisfy the specified expression.",
        "about": "requirement",
        "evidence_in_work": "email pattern contains '\\.' and valid requires email IS NOT NULL",
        "source": "email RLIKE '^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+.[A-Za-z]{2,}$'",
        "importance": 2,
        "reason": "The discrepancy affects unusual addresses but can remove the associated user entirely."
      },
      {
        "problem": "Photo URL validation accepts whitespace-prefixed and uppercase schemes while preserving the original value.",
        "about": "requirement",
        "evidence_in_work": "regexp_matches(trim(cast(r.\"photo\" AS VARCHAR)), '^https?://', 'i')",
        "source": "photo IS NULL OR photo RLIKE '^https?://'; on_failure: nullify_field",
        "importance": 2,
        "reason": "This leaves values that fail the stated URL-prefix validation."
      }
    ],
    "fewer_reason": "Three independently supported validation discrepancies were found."
  },
  "intermediate.int_lever__candidate_insights": {
    "items": [
      {
        "problem": "The required output ordering by quality score and lifecycle duration is omitted.",
        "about": "requirement",
        "evidence_in_work": "current_timestamp AS calculated_at FROM scored",
        "source": "Output rows are ordered by candidate_quality_score descending, then total_lifecycle_days ascending.",
        "importance": 2,
        "reason": "Metrics are largely implemented, but consumers do not receive the documented ranked output."
      },
      {
        "problem": "feedback_completion_rate and positive_feedback_rate are emitted as decimal expressions rather than the documented DOUBLE columns.",
        "about": "requirement",
        "evidence_in_work": "CASE WHEN tf=0 THEN 0 ELSE 100.0 END fcr; 0.0 AS positive_feedback_rate",
        "source": "feedback_completion_rate data_type: DOUBLE; positive_feedback_rate data_type: DOUBLE",
        "importance": 2,
        "reason": "The values may match, but the generated schema can violate the typed data contract."
      },
      {
        "problem": "Interview counts and duration summaries inherit interviews and durations that should have been deleted or nullified during staging.",
        "about": "requirement",
        "evidence_in_work": "count(*) total_interviews; avg(duration); sum(duration)",
        "source": "duration >= 0 AND duration <= 600; canceled_at >= created_at",
        "importance": 3,
        "reason": "The aggregate logic is sound only if upstream quality rules have been enforced."
      }
    ],
    "fewer_reason": "The remaining visible scoring, stage mapping, joins, and zero-denominator logic closely follow the supplied specification."
  },
  "intermediate.int_lever__candidate_lifecycle": {
    "items": [
      {
        "problem": "Duration calculations count whole second boundaries rather than preserving subsecond elapsed time.",
        "about": "requirement",
        "evidence_in_work": "date_diff('second', o.created_at, coalesce(o.archived_at, current_timestamp)) / 86400.0",
        "source": "Durations are in days ... with no rounding",
        "importance": 1,
        "reason": "The discrepancy is normally less than a second but affects exact unrounded duration requirements."
      },
      {
        "problem": "Invalid archive chronology retained upstream can produce lifecycle durations for opportunities that should have been excluded.",
        "about": "requirement",
        "evidence_in_work": "coalesce(o.archived_at, current_timestamp)",
        "source": "archived_at IS NULL OR try_cast(archived_at as timestamp) >= try_cast(created_at as timestamp); on_failure: delete_row",
        "importance": 3,
        "reason": "Negative or otherwise unusable lifecycle histories propagate into several marts."
      }
    ],
    "fewer_reason": "The application-level multiplicity, constants, flags, and fallback timestamps otherwise match the documented model."
  },
  "intermediate.int_lever__contact_info": {
    "items": [
      {
        "problem": "Contacts whose email rows are all null are removed instead of retained with a null emails aggregate.",
        "about": "requirement",
        "evidence_in_work": "FROM staging.stg_lever__contact_email WHERE email IS NOT NULL GROUP BY contact_id",
        "source": "One row per contact_id present in staging.stg_lever__contact_email ... result is NULL if a contact_id has no non-NULL emails.",
        "importance": 4,
        "reason": "This also discards those contacts' valid phones and profile links from opportunity enrichment."
      }
    ],
    "fewer_reason": "Phone concatenation and profile-link selection otherwise implement the supplied rules."
  },
  "intermediate.int_lever__hiring_funnel_metrics": {
    "items": [
      {
        "problem": "Stage normalization matches any 'screen' substring instead of the specified 'screening' substring.",
        "about": "requirement",
        "evidence_in_work": "lower(stage_name) LIKE '%screen%'",
        "source": "2=Initial Screening ('phone' or 'screening')",
        "importance": 4,
        "reason": "Differently named stages can change highest-stage flags, conversions, and bottleneck classifications."
      },
      {
        "problem": "The final result is not ordered by application volume and hire conversion as required.",
        "about": "requirement",
        "evidence_in_work": "FROM rates WHERE total_applications>=3",
        "source": "ordered by total_applications descending, then application_to_hired_rate descending",
        "importance": 2,
        "reason": "The documented ranking of posting results is absent."
      },
      {
        "problem": "The model does not build the specified chronological sequence markers or unique-stages-visited measure.",
        "about": "requirement",
        "evidence_in_work": "oh groups history directly using max(stage_order) and min(updated_at)",
        "source": "ordered by updated_at ... compute sequence markers (row number, previous, next); unique_stages_visited = distinct stage_id count",
        "importance": 1,
        "reason": "These omitted intermediate steps do not appear necessary for the current final columns but are explicitly requested."
      },
      {
        "problem": "The model omits several specified per-opportunity conversion durations.",
        "about": "requirement",
        "evidence_in_work": "only dscreen, dtech, and dhire are calculated",
        "source": "days_technical_to_final; days_final_to_offer; days_offer_to_hired",
        "importance": 1,
        "reason": "The omitted durations are specified processing steps even though they are not projected in the final schema."
      }
    ],
    "fewer_reason": "Four supported discrepancies were found; the unusual treatment of unknown stages as order 99 is explicitly required and was not treated as an error."
  },
  "intermediate.int_lever__interview_feedback": {
    "items": [],
    "fewer_reason": "The visible left joins, selected fields, and preservation of feedback multiplicity follow the supplied model specification."
  },
  "intermediate.int_lever__interview_users": {
    "items": [],
    "fewer_reason": "The joins and pass-through behavior match the documented model; the observed column ordering difference is not clearly prohibited by its all-columns output requirement."
  },
  "intermediate.int_lever__interviewer_performance": {
    "items": [
      {
        "problem": "advancement_rate is always null instead of measuring opportunities advanced after their interview.",
        "about": "requirement",
        "evidence_in_work": "NULL::DOUBLE advancement_rate",
        "source": "percentage of distinct opportunities where last_advanced_at is after the interview_date rounded to 1 decimal",
        "importance": 5,
        "reason": "A required outcome measure is entirely absent despite its source timestamps being selected."
      },
      {
        "problem": "overall_performance_score is always null instead of being calculated for eligible interviewers.",
        "about": "requirement",
        "evidence_in_work": "NULL::DOUBLE overall_performance_score",
        "source": "only computed when total_interviews >= 10 and feedback_completion_rate >= 80",
        "importance": 5,
        "reason": "Every eligible interviewer loses the required composite performance score."
      },
      {
        "problem": "Every interviewer is labeled Insufficient Data regardless of interview count and outcome thresholds.",
        "about": "requirement",
        "evidence_in_work": "'Insufficient Data' performance_tier",
        "source": "Insufficient Data if total_interviews < 5; otherwise Excellent ... Good ... Average ... Needs Improvement",
        "importance": 5,
        "reason": "All substantive performance-tier classification is omitted."
      },
      {
        "problem": "Outcome stage names are taken from the interview stage rather than the opportunity's current stage.",
        "about": "requirement",
        "evidence_in_work": "LEFT JOIN staging.stg_lever__stage s ON i.stage_id=s.stage_id",
        "source": "left join opportunity by opportunity_id; left join stage by stage_id ... positive_outcomes ... stage_name ... 'hire', 'accept', or 'offer'",
        "importance": 4,
        "reason": "Interview scheduling stages may not reflect later hiring outcomes, materially changing positive-outcome rates."
      },
      {
        "problem": "Grouping only by user_id with ANY_VALUE does not implement the documented grouping by user identity attributes.",
        "about": "requirement",
        "evidence_in_work": "any_value(interviewer_name) ... GROUP BY interviewer_user_id",
        "source": "Group by user_id, user_name, email, access_role, and created_at",
        "importance": 1,
        "reason": "The declared staging uniqueness normally makes this equivalent, but differing duplicate user records would be collapsed."
      },
      {
        "problem": "The 365-day filter has no upper bound, so future-dated interviews can be treated as recent activity.",
        "about": "requirement",
        "evidence_in_work": "WHERE i.interview_date>=current_timestamp-INTERVAL '365 days'",
        "source": "Only include interviews dated within the last 365 days.",
        "importance": 2,
        "reason": "If future interviews exist and the window means past activity only, activity and feedback metrics would be inflated."
      }
    ],
    "fewer_reason": "Six independently supported concerns were found; the distinct feedback-form counting and joined-row duration averaging are explicitly required."
  },
  "intermediate.int_lever__opportunity_application": {
    "items": [],
    "fewer_reason": "The visible left join, application-field selection, and preservation of multiple applications match the supplied business logic."
  },
  "intermediate.int_lever__opportunity_contact_info": {
    "items": [
      {
        "problem": "Valid phone and profile-link enrichment can be lost for contacts whose email values are all null because the joined contact model drops those contacts.",
        "about": "requirement",
        "evidence_in_work": "LEFT JOIN intermediate.int_lever__contact_info ci USING (contact_id)",
        "source": "contact_info ... One row per contact_id present in staging.stg_lever__contact_email",
        "importance": 3,
        "reason": "Opportunity rows remain, but their contact enrichment is incompletely populated."
      }
    ],
    "fewer_reason": "The local join and pass-through implementation otherwise match the specification."
  },
  "intermediate.int_lever__opportunity_tags": {
    "items": [],
    "fewer_reason": "The grouping and string aggregation preserve duplicates and exclude null tag values as specified."
  },
  "intermediate.int_lever__opportunity_users": {
    "items": [],
    "fewer_reason": "All three user joins use the documented keys and preserve the base opportunity-application rows."
  },
  "intermediate.int_lever__posting_analytics": {
    "items": [
      {
        "problem": "All interview metrics are hardcoded instead of joining applications to interviews and interviewer assignments.",
        "about": "requirement",
        "evidence_in_work": "0::BIGINT total_interviews_scheduled ... 0.0 total_interview_time_minutes",
        "source": "Join applications to interviews on opportunity_id; left join interviewer users on interview_id.",
        "importance": 5,
        "reason": "The entire interview-engagement portion of the model is absent."
      },
      {
        "problem": "Hiring, offer, and rejection outcomes are hardcoded to zero without the required opportunity and stage joins.",
        "about": "requirement",
        "evidence_in_work": "0::BIGINT candidates_hired,0::BIGINT offers_extended,0::BIGINT candidates_rejected",
        "source": "Hiring outcomes ... Join applications to opportunities; left join stages.",
        "importance": 5,
        "reason": "Core hiring outcomes are suppressed for every posting."
      },
      {
        "problem": "Advancement and contact timing statistics are fixed at zero rather than aggregated from qualifying application-opportunity timestamps.",
